use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let jobs: Vec<(i64, i64)> = input.as_array().unwrap().iter()
        .map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()))
        .collect();

    let mut total_wait_time = 0;
    let mut current_time = 0;

    for (arrival, duration) in jobs {
        if current_time < arrival {
            total_wait_time += arrival - current_time;
            current_time = arrival;
        }
        current_time += duration;
    }

    Value::from(total_wait_time)
}
